        """Split segment in to two segments at the specified column.

        If the cut point falls in the middle of a 2-cell wide character then it is replaced
        by two spaces, to preserve the display width of the parent segment.

        Returns:
            Tuple[Segment, Segment]: Two segments.
        """
        if cut <= 0:
            return Segment(), self
        if cut >= self.cell_length:
            return self, Segment()

        pos = 0
        text, style, control = self
        lower = 0
        upper = len(text)
        target_len = cut

        while upper > lower:
            divide_pos = (upper + lower) // 2
            before = text[:divide_pos]
            after = text[divide_pos:]
            before_len = cell_len(before)

            if before_len == target_len + 1 and cell_len(before[-1]) == 2:
                before = f"{before[:-1]} "
                after = f" {after}"
                before_len -= 1

            if before_len == target_len:
                if before:
                    return Segment(before, style, control), Segment(after, style, control)
                else:
                    return Segment(), self

            if before_len < target_len:
                lower = divide_pos + 1
            else:
                upper = divide_pos

